/**
 * Agent UI catalog: which component the harness renders for which moment of an
 * agent run, what sets it off, and what the agent says around it.
 *
 * One source for three readers: the docs site (each component page shows its
 * row under "In the stream"), docs/AGENT_UI.md (generated by
 * `npm run docs:agent-ui`, read by agents), and the harness that turns the
 * Claude Code stream into thread parts. Plain data only: no React, no imports,
 * so Node can read it directly.
 *
 * Triggers come from three places:
 *   stream  an event in Claude Code's stream-json output (thinking, tool_use, result…)
 *   tool    a call to one of our MCP tools (mcp__spontaneous__*). `proposed` tools are
 *           the contract this catalog asks for; `existing` ones are served today.
 *   app     state the app owns and shows on its own (the command log, usage, export jobs)
 */

export type TriggerSource = "stream" | "tool" | "app";

export interface Trigger {
  source: TriggerSource;
  /** The stream event, the tool name, or the app event. */
  event: string;
  /** For tools: whether the MCP server already serves it. */
  status?: "existing" | "proposed";
}

export interface AgentSurface {
  /** Docs page id: /docs.html#<id>. */
  id: string;
  /** Component(s) to render, as imported. */
  component: string;
  /** Import path. */
  from: string;
  /** The moment in a run this surface belongs to, in one sentence. */
  moment: string;
  trigger: Trigger;
  /** What the person says that typically leads here. */
  youSay?: string;
  /** What the agent streams as text around it, verbatim style. */
  agentSays: string;
  /** The event or tool call that sets it off, as JSON-ish text. */
  payload?: string;
  /** How the payload maps to props. */
  props: string;
  /** When to pick something else, and what. */
  instead?: string;
  /** Its keys: which one competes for the primary, with what intent, and how it's worded. */
  keys?: string;
}

export type SurfaceGroup = "While it thinks" | "While it works" | "Before it acts" | "What it changed" | "Answers and suggestions" | "Around the run";

export const SURFACE_GROUPS: { group: SurfaceGroup; ids: string[] }[] = [
  { group: "While it thinks", ids: ["thinking-loader", "thinking-state"] },
  { group: "While it works", ids: ["tool-call", "agent-plan", "agent-steering", "agent-monitor", "parallel-attempts"] },
  { group: "Before it acts", ids: ["ask", "approval-card", "permission-request", "autonomy-dial"] },
  { group: "What it changed", ids: ["agent-ledger", "agent-checkpoints", "inline-diff", "note-thread", "message-actions"] },
  { group: "Answers and suggestions", ids: ["cited-answer", "shot-suggestion"] },
  { group: "Around the run", ids: ["agent-thread", "chat-composer", "model-picker", "context-window", "command-menu", "dropzone", "toaster", "getting-started"] },
];

/**
 * Choosing a surface, in the order the harness should ask the questions.
 * The first rule that matches wins.
 */
export const CHOOSING: [when: string, use: string][] = [
  ["Nothing has streamed yet after a send", "thinking-loader; switch to thinking-state as soon as a thinking block or a read tool arrives"],
  ["The agent is reading (thinking, get_project, get_input_events, render_frame) before its first edit", "thinking-state, with each frame or input range it read as a moment"],
  ["A run will make three or more edits", "agent-plan first (propose_plan), then let the same card run"],
  ["The agent calls a write tool that is reversible", "tool-call inside a tool-call group; the edit lands in agent-ledger"],
  ["The agent calls a write tool that is hard to undo (overwrite, delete, replace audio)", "approval-card, unless autonomy-dial says it runs on its own"],
  ["The agent needs a right it doesn't have (outside the project, network, a device)", "permission-request"],
  ["The agent can't decide between a few directions of taste", "ask (ask_user) for 2–4 short options; shot-suggestion when it has a favorite shot"],
  ["The agent wants to change words: captions, the script, on-screen text, the title", "inline-diff (propose_text_edit), never a silent rewrite"],
  ["The agent answers a question about the recording", "cited-answer, citing the moments it looked at"],
  ["The agent tries the same edit several ways", "parallel-attempts (try_variants)"],
  ["A run takes longer than about 20 seconds (render, export, a long batch of notes)", "agent-monitor"],
  ["The person types while a run is going", "agent-steering: queue the note for the next step, ⌘↵ to apply now"],
  ["The agent replied to a specific note", "note-thread on that note; resolve_annotation links the edits"],
  ["A turn ends", "message-actions under the last text; agent-checkpoints saves a checkpoint if anything changed"],
  ["Something finished outside the panel (export done, copy, background error)", "toaster"],
];

/**
 * Wording the keys. Any UI tool call may carry
 *   "cta": { "primary": { "label": "Tighten the intro", "intent": "run" }, "secondary": [{ "label": "Keep current" }] }
 * The app shows the agent's label when it passes these rules and its own
 * derived label otherwise (src/ui/cta/validate.ts), so a CTA is never missing
 * or wrong. Which key is primary on a surface is decided by the app, not the agent.
 */
export const CTA_RULES: string[] = [
  "Start with a verb that says what happens: Apply, Run, Cut, Zoom, Replace, Allow, Accept, Use, Export. Never Confirm, OK, Yes, Submit, Continue.",
  "Name the object, and a count or a time when it helps: “Apply zoom at 0:12”, “Delete 3 takes”, “Run 5 edits”.",
  "Four words and 28 characters at most. Sentence case. No !, ?, … or emoji.",
  "A number must match what the action touches: “Apply 3 notes” only when there are 3.",
  "Destructive actions name what they destroy (“Overwrite export”, not “Overwrite”); the key turns red on its own.",
  "The intent ranks it: decide (approve, allow) > run (start work) > review (accept changes) > apply (take a suggestion) > finish (export) > navigate. Dismiss (Deny, Keep current, Cancel) is never primary. Several asks waiting: the oldest holds the primary, so they're answered in the order you made them.",
  "Leave the label out when the derived one already says it: the app writes “Run 5 edits”, “Accept 4 changes”, “Allow for an hour” itself.",
];

export const CTA_EXAMPLES: [intent: string, good: string, bad: string][] = [
  ["decide", "Replace audio · Delete 3 takes · Allow for an hour", "Confirm · OK · Yes, do it!"],
  ["run", "Run 5 edits · Apply zoom at 0:12 · Tighten the intro", "Apply · Go · Start the whole thing now"],
  ["review", "Accept 4 changes · Keep the shorter one", "Accept · Looks good 🎉"],
  ["apply", "Use Lid Rise · Apply as 3 edits", "Use it · Apply suggestion"],
  ["finish", "Export 1080p · Export for Slack", "Done · Finish"],
];

/**
 * UI blocks: how the agent brings up a component while it has no tools. It
 * writes a fenced block in its reply, named after the tool it stands for, and
 * the app turns it into that tool's part (src/editor/agent-stream.ts). The
 * shape here is exactly what the app reads; the answer is what it sends back,
 * after a line worded as the key the person pressed, inside
 * <spontaneous-answer tool="…" id="…">…</spontaneous-answer>.
 */
export interface BlockSpec {
  tool: string;
  /** When to write it, in one line. */
  when: string;
  /** The payload, as compact JSON with example values. Optional fields are marked "?". */
  shape: string;
  /** What comes back when the person answers. */
  answer: string;
}

